/*# sourceURL=/wp-includes/css/classic-themes.min.css */ .adda-score-calc {
            --asc-ink: #1a2e35;
            --asc-paper: #fbf9f4;
            --asc-line: #d8d2c4;
            --asc-accent: #ff2a05;
            --asc-accent-soft: #e4efec;
            --asc-fail: #a13d2b;
            --asc-fail-soft: #f6e9e5;
            font-family: -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
            color: var(--asc-ink);
            background: var(--asc-paper);
            border: 1px solid var(--asc-line);
            border-radius: 10px;
            max-width: 640px;
            margin: 24px auto;
            padding: 10px 15px;
            box-sizing: border-box;
        }
        .adda-score-calc *, .adda-score-calc *::before, .adda-score-calc *::after {
            box-sizing: border-box;
        }
        .adda-score-calc .adda-sc-eyebrow {

            color: var(--asc-accent);

        }
        .adda-score-calc .adda-sc-title {
            margin: 0 0 4px;
            font-size: 22px;
            line-height: 1.25;
            font-weight: 700;
        }
        .adda-score-calc .adda-sc-sub {
            margin: 0 0 22px;
            font-size: 14px;
            color: #5b6b70;
        }
        .adda-score-calc .adda-sc-field {
            margin-bottom: 16px;
        }
        .adda-score-calc label {
            display: block;
            font-size: 13px;
            font-weight: 600;
            margin-bottom: 6px;
        }
        .adda-score-calc select,
        .adda-score-calc input[type="number"] {
            width: 100%;
            font-size: 15px;
            padding: 10px 12px;
            border: 1px solid var(--asc-line);
            border-radius: 7px;
            background: #fff;
            color: var(--asc-ink);
            font-family: inherit;
        }
        .adda-score-calc select:focus,
        .adda-score-calc input[type="number"]:focus {
            outline: 2px solid var(--asc-accent);
            outline-offset: 1px;
            border-color: var(--asc-accent);
        }
        .adda-score-calc .adda-sc-row {
            display: flex;
            gap: 14px;
            flex-wrap: wrap;
        }
        .adda-score-calc .adda-sc-row .adda-sc-field {
            flex: 1 1 220px;
        }
        .adda-score-calc .adda-sc-requirement {
            display: flex;
            align-items: baseline;
            justify-content: space-between;
            background: var(--asc-accent-soft);
            border: 1px solid var(--asc-line);
            border-radius: 7px;
            padding: 10px 14px;
            font-size: 13px;
            margin-bottom: 18px;
        }
        .adda-score-calc .adda-sc-requirement strong {
            font-size: 15px;
        }
        .adda-score-calc .adda-sc-raw-breakdown {
            border: 1px solid var(--asc-line);
            border-radius: 8px;
            overflow: hidden;
            margin-bottom: 16px;
        }
        .adda-score-calc .adda-sc-raw-row {
            display: flex;
            align-items: baseline;
            justify-content: space-between;
            padding: 10px 14px;
            font-size: 13px;
            background: #fff;
            border-bottom: 1px solid var(--asc-line);
        }
        .adda-score-calc .adda-sc-raw-row:last-child {
            border-bottom: none;
        }
        .adda-score-calc .adda-sc-raw-row strong {
            font-size: 15px;
        }
        .adda-score-calc .adda-sc-raw-total {
            background: var(--asc-accent-soft);
        }
        .adda-score-calc .adda-sc-raw-total strong {
            color: var(--asc-accent);
            font-size: 17px;
        }
        .adda-score-calc .adda-sc-result {
            border-radius: 8px;
            padding: 16px 18px;
            display: none;
            align-items: flex-start;
            gap: 12px;
        }
        .adda-score-calc .adda-sc-result.show { display: flex; }
        .adda-score-calc .adda-sc-result.pass {
            background: var(--asc-accent-soft);
            border: 1px solid var(--asc-accent);
        }
        .adda-score-calc .adda-sc-result.fail {
            background: var(--asc-fail-soft);
            border: 1px solid var(--asc-fail);
        }
        .adda-score-calc .adda-sc-result-icon {
            font-size: 22px;
            line-height: 1;
            flex-shrink: 0;
        }
        .adda-score-calc .adda-sc-result-title {
            font-weight: 700;
            font-size: 15px;
            margin: 0 0 3px;
        }
        .adda-score-calc .adda-sc-result.pass .adda-sc-result-title { color: var(--asc-accent); }
        .adda-score-calc .adda-sc-result.fail .adda-sc-result-title { color: var(--asc-fail); }
        .adda-score-calc .adda-sc-result-detail {
            font-size: 13px;
            color: #4a4a4a;
            margin: 0;
        }
        .adda-score-calc .adda-sc-note {
            margin-top: 16px;
            font-size: 11.5px;
            color: #8a8a8a;
            line-height: 1.5;
        }

/*# sourceURL=adda-score-calc-style-inline-css */ .adda-image-cropper {
            --aic-ink: #1a2e35;
            --aic-paper: #fbf9f4;
            --aic-line: #d8d2c4;
            --aic-accent: #0f6b5c;
            --aic-accent-soft: #e4efec;
            color: var(--aic-ink);
            background: var(--aic-paper);
            border: 1px solid var(--aic-line);
            border-radius: 5px;
            max-width: 420px;
            margin: 24px auto;
            padding: 24px;
            text-align: center;
        }
        .adda-image-cropper *, .adda-image-cropper *::before, .adda-image-cropper *::after {
            box-sizing: border-box;
        }
        .adda-image-cropper .aic-tabs {
            display: flex;
            justify-content: center;
            flex-wrap: wrap;
            gap: 8px;
            margin-bottom: 10px;
        }
        .adda-image-cropper .aic-tab {
            font-family: inherit;
            font-size: 13px;
            font-weight: 600;
            padding: 8px 16px;
            border: 1px solid var(--aic-line);
            border-radius: 5px;
            background: var(--aic-paper);
            color: var(--aic-ink);
            cursor: pointer;
            transition: background .15s ease, border-color .15s ease, color .15s ease;
        }
        .adda-image-cropper .aic-tab:hover {
            border-color: var(--aic-accent);
        }
        .adda-image-cropper .aic-tab.active {
            background: var(--aic-accent);
            border-color: var(--aic-accent);
            color: var(--aic-paper);
        }
        .adda-image-cropper .aic-size-label {
            margin: 0 0 18px;
            font-size: 12.5px;
            color: #5b6b70;
        }
        .adda-image-cropper .aic-upload {
            border: 2px dashed var(--aic-line);
            border-radius: 5px;
            padding: 28px 16px;
            background: var(--aic-paper);
        }
        .adda-image-cropper .aic-upload p {
            margin: 0 0 12px;
            font-size: 13px;
            color: #5b6b70;
        }
        .adda-image-cropper .aic-upload-btn {
            display: inline-block;
            font-size: 14px;
            font-weight: 700;
            padding: 10px 22px;
            border-radius: 5px;
            background: var(--aic-accent);
            color: var(--aic-paper);
            cursor: pointer;
        }
        .adda-image-cropper .aic-upload-btn:hover {
            background: #0c5749;
        }
        .adda-image-cropper .aic-stage {
            position: relative;
            width: 100%;
            max-width: 260px;
            margin: 0 auto;
            overflow: hidden;
            border-radius: 5px;
            border: 4px solid var(--aic-paper);
            background: #eee;
            cursor: grab;
        }
        .adda-image-cropper .aic-stage:active {
            cursor: grabbing;
        }
        .adda-image-cropper .aic-image {
            position: absolute;
            top: 0;
            left: 0;
            max-width: none;
            user-select: none;
            -webkit-user-drag: none;
            pointer-events: none;
        }
        .adda-image-cropper .aic-zoom-row {
            display: flex;
            align-items: center;
            gap: 10px;
            max-width: 260px;
            margin: 16px auto 0;
        }
        .adda-image-cropper .aic-zoom-row input[type="range"] {
            flex: 1;
            accent-color: var(--aic-accent);
        }
        .adda-image-cropper .aic-zoom-icon {
            font-size: 16px;
            font-weight: 700;
            color: #5b6b70;
            flex-shrink: 0;
        }
        .adda-image-cropper .aic-crop-btn {
            margin-top: 18px;
            font-family: inherit;
            font-size: 14px;
            font-weight: 700;
            padding: 10px 26px;
            border-radius: 5px;
            border: none;
            background: var(--aic-accent);
            color: #fff;
            cursor: pointer;
        }
        .adda-image-cropper .aic-crop-btn:hover {
            background: #0c5749;
        }
        .aic-stage-overlay {
            background: #d7f1d8;
            padding: 20px;
            width: 300px;
            margin: auto;
        }
        .aic-mobile-overlay {
            position: fixed;
            top: 0; left: 0; right: 0; bottom: 0;
            background: rgba(0,0,0,.6);
            display: flex;
            align-items: center;
            justify-content: center;
            z-index: 99999;
        }
        .aic-mobile-modal {
            background: #fff;
            border-radius: 5px;
            padding: 24px;
            width: 90%;
            max-width: 320px;
            text-align: center;
            font-family: -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
            color: #1a2e35;
        }
        .aic-mobile-modal h4 {
            margin: 0 0 8px;
            font-size: 16px;
        }
        .aic-mobile-modal p {
            margin: 0 0 14px;
            font-size: 13px;
            color: #5b6b70;
        }
        .aic-mobile-input {
            width: 100%;
            font-size: 15px;
            padding: 10px 12px;
            border: 1px solid #d8d2c4;
            border-radius: 5px;
            margin-bottom: 6px;
            box-sizing: border-box;
        }
        .aic-mobile-error {
            color: #a13d2b !important;
            font-size: 12px !important;
            min-height: 14px;
        }
        .aic-mobile-actions {
            display: flex;
            gap: 10px;
            margin-top: 10px;
        }
        .aic-mobile-actions button {
            flex: 1;
            font-family: inherit;
            font-size: 14px;
            font-weight: 700;
            padding: 10px;
            border-radius: 5px;
            border: none;
            cursor: pointer;
        }
        .aic-mobile-submit {
            background: #0f6b5c;
            color: #fff;
        }
        .aic-mobile-submit:hover {
