	text-transform: capitalize;
}
.top-performing-box .slider-container {
	overflow: hidden;
	position: relative;
	display: flex;
	align-items: center;
	margin-left:20px;
	margin-right:10px;
	width:80%;
}
.top-performing-box .heading {
	background: #FC3A52;
	color: #fff;
	font-size:13px;
	padding: 2px 8px;
	text-transform: uppercase;
	white-space: nowrap;
	z-index: 2
}
.top-performing-box .heading:after {
	background: #FC3A52;
	content: "";
	display: block;
	height: 21px;
	right: calc(100% - 145px);
