            function initCalculator(root) {
                var type = root.getAttribute('data-type');
                if (type === 'raw_score') {
                    initRawScoreCalculator(root);
                } else {
                    initQualifyingCalculator(root);
                }
            }

            function initQualifyingCalculator(root) {
                var totalMarks = parseFloat(root.getAttribute('data-total')) || 0;
                var categories = {};
                try {
                    categories = JSON.parse(root.getAttribute('data-categories') || '{}');
                } catch (e) {
                    categories = {};
                }

                var categoryEl = root.querySelector('.adda-sc-category');
                var marksEl = root.querySelector('.adda-sc-marks');
                var reqBox = root.querySelector('.adda-sc-requirement');
                var reqValue = root.querySelector('.adda-sc-requirement-value');
                var resultBox = root.querySelector('.adda-sc-result');
                var resultIcon = root.querySelector('.adda-sc-result-icon');
                var resultTitle = root.querySelector('.adda-sc-result-title');
                var resultDetail = root.querySelector('.adda-sc-result-detail');

                if (!categoryEl || !marksEl) return;

                function reset() {
                    resultBox.classList.remove('show', 'pass', 'fail');
                }

                function update() {
                    var cat = categoryEl.value;
                    var marksRaw = marksEl.value;

                    if (!cat || !categories[cat]) {
                        reqBox.style.display = 'none';
                        reset();
                        return;
                    }

                    var req = categories[cat];
                    reqBox.style.display = 'flex';
                    reqValue.textContent = req.marks + ' / ' + totalMarks + ' (' + req.percent + '%)';

                    if (marksRaw === '') {
                        reset();
                        return;
                    }

                    var marks = parseFloat(marksRaw);
                    if (isNaN(marks)) {
                        reset();
                        return;
                    }
                    if (marks > totalMarks) {
                        alert('Maximum marks for this exam is ' + totalMarks + '. Please enter a value between 0 and ' + totalMarks + '.');
                        marksEl.value = '';
                        reset();
                        return;
                    }
                    if (marks < 0) marks = 0;

                    var passed = marks >= req.marks;
                    resultBox.classList.add('show');
                    resultBox.classList.remove(passed ? 'fail' : 'pass');
                    resultBox.classList.add(passed ? 'pass' : 'fail');

                    resultIcon.textContent = passed ? '✓' : '✗';
                    resultTitle.textContent = passed
                        ? 'Qualified — you’ve met the cut-off'
                        : 'Not qualified — below the cut-off';

                    var short = req.marks - marks;
                    resultDetail.textContent = passed
                        ? 'Your score of ' + marks + '/' + totalMarks + ' clears the ' + req.label + ' requirement of ' + req.marks + '/' + totalMarks + ' (' + req.percent + '%) by ' + (marks - req.marks) + ' mark(s).'
                        : 'Your score of ' + marks + '/' + totalMarks + ' is short of the ' + req.label + ' requirement of ' + req.marks + '/' + totalMarks + ' (' + req.percent + '%) by ' + short + ' mark(s).';
                }

                categoryEl.addEventListener('change', update);
                marksEl.addEventListener('input', update);
            }

            function initRawScoreCalculator(root) {
                var totalMarks = parseFloat(root.getAttribute('data-total')) || 0;
                var negativeMarks = parseFloat(root.getAttribute('data-negative')) || 0;
                var perQuestionMark = parseFloat(root.getAttribute('data-per-question')) || 1;

                var correctEl = root.querySelector('.adda-sc-correct');
                var incorrectEl = root.querySelector('.adda-sc-incorrect');
                var positiveOut = root.querySelector('.adda-sc-positive-marks');
                var negativeOut = root.querySelector('.adda-sc-negative-marks');
                var rawOut = root.querySelector('.adda-sc-raw-score');

                if (!correctEl || !incorrectEl) return;

                function round2(n) {
                    return Math.round(n * 100) / 100;
                }

                function update() {
                    var correct = parseFloat(correctEl.value);
                    var incorrect = parseFloat(incorrectEl.value);
                    correct = isNaN(correct) || correct < 0 ? 0 : correct;
                    incorrect = isNaN(incorrect) || incorrect < 0 ? 0 : incorrect;

                    if (totalMarks && (correct + incorrect) > totalMarks) {
                        alert('Correct + Incorrect answers cannot exceed the total of ' + totalMarks + ' questions.');
                        if (document.activeElement === incorrectEl) {
                            incorrectEl.value = '';
                            incorrect = 0;
                        } else {
                            correctEl.value = '';
                            correct = 0;
                        }
                    }

                    var positive = round2(correct * perQuestionMark);
                    var negative = round2(incorrect * perQuestionMark * negativeMarks);
                    var raw = round2(positive - negative);

                    positiveOut.textContent = positive;
                    negativeOut.textContent = negative;
                    rawOut.textContent = raw;
                }

                correctEl.addEventListener('input', update);
                incorrectEl.addEventListener('input', update);
                update();
            }

            document.addEventListener('DOMContentLoaded', function () {
                var roots = document.querySelectorAll('.adda-score-calc');
                for (var i = 0; i < roots.length; i++) {
                    initCalculator(roots[i]);
                }
            });
