    document.querySelectorAll('.wp-faq-schema-accordion .wp-faq-schema-items').forEach(function(section) {
        var headers = section.querySelectorAll(':scope > h3');
        var panels = section.querySelectorAll(':scope > div');

        // Clean jQuery UI attributes
        headers.forEach(function(h) {
            h.className = ''; h.removeAttribute('role'); h.removeAttribute('aria-controls');
            h.removeAttribute('aria-selected'); h.removeAttribute('aria-expanded');
            h.removeAttribute('tabindex'); h.removeAttribute('id');
