            p.removeAttribute('aria-hidden'); p.removeAttribute('id'); p.style.display = '';
        });
        section.className = 'wp-faq-schema-items';

        // Open first by default
        if (headers[0]) headers[0].classList.add('faq-active');
        if (panels[0]) panels[0].classList.add('faq-open');

        // Click toggle
        headers.forEach(function(header, i) {
            header.addEventListener('click', function() {
                var wasActive = this.classList.contains('faq-active');
                headers.forEach(function(h) { h.classList.remove('faq-active'); });
                panels.forEach(function(p) { p.classList.remove('faq-open'); });
                if (!wasActive) {
                    this.classList.add('faq-active');
                    if (panels[i]) panels[i].classList.add('faq-open');
                }
            });
        });
    });
